using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;
public static class MyeongjiGroundFloor {
 const string Folder="Assets/_Game/Art/Myeongji/Geometry/StreetFronts";const float Height=3.16f;
 struct Opening {public float a,b,bottom,top;public bool door;public Opening(float x,float w,float y,float h,bool d=false){a=x-w/2;b=x+w/2;bottom=y;top=y+h;door=d;}}
 class Builder {
 public Transform tr;public float edge,sign;public List<Vector3> vertices=new List<Vector3>();public List<int>[] ids;public Builder(Transform t,float e,float s,int mats){tr=t;edge=e;sign=s;ids=Enumerable.Range(0,mats).Select(_=>new List<int>()).ToArray();}
 public Vector3 P(float x,float y,float d)=>new Vector3(x,y,edge+sign*d);
 public void Poly(List<Vector3> p,int mat){for(int i=1;i<p.Count-1;i++){if(Vector3.Cross(p[i]-p[0],p[i+1]-p[0]).sqrMagnitude<1e-12f)continue;int n=vertices.Count;vertices.Add(tr.InverseTransformPoint(p[0]));vertices.Add(tr.InverseTransformPoint(p[i]));vertices.Add(tr.InverseTransformPoint(p[i+1]));ids[mat].AddRange(new[]{n,n+1,n+2});}}
 void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,int mat,Vector3 normal){var p=new List<Vector3>{a,b,c,d};if(Vector3.Dot(Vector3.Cross(b-a,c-a),normal)<0)p.Reverse();Poly(p,mat);}
 public void Box(float a,float b,float low,float high,float back,float front,int mat){if(b-a<.001f||high-low<.001f||front-back<.001f)return;var A=P(a,low,back);var B=P(b,low,back);var C=P(b,high,back);var D=P(a,high,back);var E=P(a,low,front);var F=P(b,low,front);var G=P(b,high,front);var H=P(a,high,front);var outN=Vector3.forward*sign;Quad(E,F,G,H,mat,outN);Quad(A,D,C,B,mat,-outN);Quad(A,E,H,D,mat,Vector3.left);Quad(B,C,G,F,mat,Vector3.right);Quad(D,H,G,C,mat,Vector3.up);Quad(A,B,F,E,mat,Vector3.down);}
 public void Canopy(float x,float width,int mat){ // A short, plain sloping canopy. All edges stay above head height.
 float a=x-width/2,b=x+width/2;var p=new[]{P(a,3.12f,-.08f),P(b,3.12f,-.08f),P(b,3.00f,.60f),P(a,3.00f,.60f),P(a,3.25f,-.08f),P(b,3.25f,-.08f),P(b,3.13f,.60f),P(a,3.13f,.60f)};Quad(p[4],p[5],p[6],p[7],mat,Vector3.up);Quad(p[0],p[3],p[2],p[1],mat,Vector3.down);Quad(p[3],p[7],p[6],p[2],mat,Vector3.forward*sign);Quad(p[0],p[1],p[5],p[4],mat,-Vector3.forward*sign);Quad(p[0],p[4],p[7],p[3],mat,Vector3.left);Quad(p[1],p[2],p[6],p[5],mat,Vector3.right);}
 public Mesh Mesh(string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(vertices);m.subMeshCount=ids.Length;for(int i=0;i<ids.Length;i++)m.SetTriangles(ids[i],i);m.RecalculateNormals();m.RecalculateBounds();return m;}
 }
 static void Split(List<Vector3> p,Func<Vector3,float> distance,out List<Vector3> inside,out List<Vector3> outside){inside=new List<Vector3>();outside=new List<Vector3>();if(p.Count==0)return;var a=p.Last();float da=distance(a);foreach(var b in p){float db=distance(b);if((da>=0)!=(db>=0)){var v=Vector3.Lerp(a,b,da/(da-db));inside.Add(v);outside.Add(v);}if(db>=0)inside.Add(b);else outside.Add(b);a=b;da=db;}}
 static void KeepSource(Builder build,Mesh source,bool cut){var v=source.vertices.Select(p=>build.tr.TransformPoint(p)).ToArray();for(int s=0;s<source.subMeshCount;s++){var ids=source.GetTriangles(s);for(int i=0;i<ids.Length;i+=3){var poly=new List<Vector3>{v[ids[i]],v[ids[i+1]],v[ids[i+2]]};var planes=cut?new Func<Vector3,float>[]{p=>Height-p.y,p=>p.y+.001f,p=>build.sign*(p.z-build.edge)+.64f,p=>.01f-build.sign*(p.z-build.edge)}:new Func<Vector3,float>[]{p=>2.64f-p.y,p=>p.y-.24f,p=>p.x-72.60f,p=>73.90f-p.x,p=>build.sign*(p.z-build.edge)+.235f,p=>.02f-build.sign*(p.z-build.edge)};foreach(var plane in planes){Split(poly,plane,out var inner,out var outer);build.Poly(outer,s);poly=inner;if(poly.Count<3)break;}}}}
 static void Infill(Builder b,float left,float right,Opening[] holes){var xs=holes.SelectMany(h=>new[]{h.a,h.b}).Concat(new[]{left,right}).OrderBy(x=>x).Distinct().ToArray();var ys=holes.SelectMany(h=>new[]{h.bottom,h.top}).Concat(new[]{0f,.22f,Height}).OrderBy(y=>y).Distinct().ToArray();for(int i=1;i<xs.Length;i++)for(int j=1;j<ys.Length;j++){float x=(xs[i-1]+xs[i])/2,y=(ys[j-1]+ys[j])/2;if(holes.Any(h=>x>h.a&&x<h.b&&y>h.bottom&&y<h.top))continue;b.Box(xs[i-1],xs[i],ys[j-1],ys[j],-.64f,0,y<.22f?2:0);}
 foreach(var h in holes){float t=h.door?.10f:.09f;float glassFront=h.door?-.42f:-.32f; // Frames border the glass; no coplanar overlay.
 b.Box(h.a+t,h.b-t,h.bottom+t,h.top-t,glassFront-.045f,glassFront,1);
 b.Box(h.a,h.a+t,h.bottom,h.top,-.50f,-.08f,3);b.Box(h.b-t,h.b,h.bottom,h.top,-.50f,-.08f,3);
 b.Box(h.a+t,h.b-t,h.top-t,h.top,-.50f,-.08f,3);b.Box(h.a+t,h.b-t,h.bottom,h.bottom+t,-.50f,-.08f,3);
 if(h.door){float center=(h.a+h.b)/2;if(h.b-h.a>1.4f)b.Box(center-.035f,center+.035f,h.bottom+t,h.top-t,-.40f,-.31f,3);float handle=center+(h.b-h.a>1.4f?.13f:.30f);b.Box(handle-.025f,handle+.025f,.98f,1.40f,-.32f,-.20f,2);b.Box(h.a,h.b,0,.035f,-.64f,.04f,2);}
 else{float center=(h.a+h.b)/2;b.Box(center-.035f,center+.035f,h.bottom+t,h.top-t,-.30f,-.18f,3);b.Box(h.a-.05f,h.b+.05f,h.bottom-.07f,h.bottom,-.10f,.12f,2);}
 }}
 static GameObject Map=>SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");
 static string Apply(string[] names){var scene=SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.isDirty||scene.path!="Assets/_Game/Scenes/FourDistrictPrototype_Myeongji.unity")throw new Exception("Saved Myeongji edit scene required");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/_Game/Art/Myeongji/Geometry","StreetFronts");var rows=new List<string>();
 foreach(string id in names){string path=Folder+"/"+id+"_GroundFloor.asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)!=null)throw new Exception(id+" already applied");var r=Map.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name=="AB01_"+id+".001");var f=r.GetComponent<MeshFilter>();var col=r.GetComponent<MeshCollider>();var old=f.sharedMesh;var bounds=r.bounds;bool north=id!="B06";float sign=north?1:-1,edge=north?bounds.max.z:bounds.min.z;var materials=r.sharedMaterials.ToList();var accent=Map.GetComponentsInChildren<Renderer>().SelectMany(v=>v.sharedMaterials).First(m=>m!=null&&m.name=="KIT_DistrictWall_A9B5A1");materials.Add(accent);var b=new Builder(r.transform,edge,sign,materials.Count);bool cut=id!="B03";KeepSource(b,old,cut);float center=bounds.center.x;string style;
 if(id=="B02"){style="Shopfront with central double entrance";Infill(b,bounds.min.x,bounds.max.x,new[]{new Opening(center,1.65f,.035f,2.58f,true),new Opening(center-3.2f,3.7f,.36f,2.30f),new Opening(center+3.2f,3.7f,.36f,2.30f)});b.Canopy(center-3.2f,4.1f,4);b.Canopy(center+3.2f,4.1f,4);}
 else if(id=="B04"){style="Shared lobby and paired raised windows";Infill(b,bounds.min.x,bounds.max.x,new[]{new Opening(center,1.8f,.035f,2.52f,true),new Opening(center-3.25f,2.6f,.9f,1.55f),new Opening(center+3.25f,2.6f,.9f,1.55f)});b.Canopy(center,2.7f,2);}
 else if(id=="B05"){style="Small residence with offset entrance";Infill(b,bounds.min.x,bounds.max.x,new[]{new Opening(bounds.max.x-1.05f,1.12f,.035f,2.3f,true),new Opening(bounds.min.x+1.25f,1.5f,1.05f,1.2f)});b.Canopy(bounds.max.x-1.05f,1.65f,2);}
 else if(id=="B06"){style="Alley residence with central recessed lobby";Infill(b,bounds.min.x,bounds.max.x,new[]{new Opening(center,1.55f,.035f,2.4f,true),new Opening(center-3.15f,1.8f,1.05f,1.25f),new Opening(center+3.15f,1.8f,1.05f,1.25f)});b.Canopy(center,2.25f,4);}
 else {style="Existing stepped shopfront retained, glazed entry added";float x=73.25f; // Reuse the existing right-hand shop opening; retain the stepped building silhouette.
 b.Box(x-.56f,x+.56f,.35f,2.52f,-.20f,-.15f,1);b.Box(x-.65f,x-.56f,.24f,2.64f,-.21f,-.035f,3);b.Box(x+.56f,x+.65f,.24f,2.64f,-.21f,-.035f,3);b.Box(x-.56f,x+.56f,2.52f,2.64f,-.21f,-.035f,3);b.Box(x-.56f,x+.56f,.24f,.35f,-.21f,-.035f,3);b.Box(x+.32f,x+.37f,1.04f,1.44f,-.13f,-.045f,2);b.Canopy(74.5f,4.6f,4);}
 var mesh=b.Mesh(id+"_GroundFloor");AssetDatabase.CreateAsset(mesh,path);f.sharedMesh=mesh;col.sharedMesh=mesh;r.sharedMaterials=materials.ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(col);PrefabUtility.RecordPrefabInstancePropertyModifications(r);rows.Add(id+": "+style+"; "+mesh.vertexCount+" vertices");
 }
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.AppendAllLines("Docs/MapLayout/Myeongji/ground_floor_batch01.txt",rows);return string.Join("\n",rows);}
 public static string First()=>Apply(new[]{"B02","B04"});public static string Second()=>Apply(new[]{"B05","B06","B03"});
 public static string SavePrefab(){PrefabUtility.SaveAsPrefabAsset(Map,"Assets/_Game/Prefabs/Myeongji/MyeongjiMap.prefab",out bool ok);if(!ok)throw new Exception("Prefab save failed");AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return "Map prefab and scene saved";}
}
